import{_ as o,C as n,o as d,c as i,j as e,a,b as s,w as r,E,a2 as p,a3 as B}from"./chunks/framework.C51MRPOx.js";const b=JSON.parse('{"title":"KV 缓存与前缀缓存","description":"","frontmatter":{},"headers":[],"relativePath":"LLM推理/KV缓存与前缀缓存.md","filePath":"LLM推理/KV缓存与前缀缓存.md","lastUpdated":null}'),u={name:"LLM推理/KV缓存与前缀缓存.md"};function k(m,t,h,A,f,V){const l=n("Mermaid");return d(),i("div",null,[t[1]||(t[1]=e("h1",{id:"kv-缓存与前缀缓存",tabindex:"-1"},[a("KV 缓存与前缀缓存 "),e("a",{class:"header-anchor",href:"#kv-缓存与前缀缓存","aria-label":'Permalink to "KV 缓存与前缀缓存"'},"​")],-1)),t[2]||(t[2]=e("blockquote",null,[e("p",null,"生成下一个 token 时，模型要看前面每个 token 的键和值，这些键值就是 KV cache，留在显存里。Decode 每一步只追加最新一个 token 的键值，整段提示不用重算。")],-1)),t[3]||(t[3]=e("p",null,"没有这块缓存，每生成一个字都要把从第一个 token 到当前位置全部重算，延迟随已生成长度明显变长；有了它，每步计算量大致稳定，显存占用则随上下文变长而上升。",-1)),t[4]||(t[4]=e("h2",{id:"显存先给权重-剩下的切成块",tabindex:"-1"},[a("显存先给权重，剩下的切成块 "),e("a",{class:"header-anchor",href:"#显存先给权重-剩下的切成块","aria-label":'Permalink to "显存先给权重，剩下的切成块"'},"​")],-1)),t[5]||(t[5]=e("p",null,"显存先放下权重——体积由参数量和量化位数决定，服务跑起来后基本不动。剩下的空间按显存占用比例切成固定长度的 KV 块。",-1)),(d(),s(p,null,{default:r(()=>[E(l,{id:"mermaid-17",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20W%5B%22%E6%9D%83%E9%87%8D%3Cbr%2F%3E%E5%85%88%E5%8D%A0%E6%98%BE%E5%AD%98%22%5D%20--%3E%20S%5B%22%E5%89%A9%E4%BD%99%E6%98%BE%E5%AD%98%3Cbr%2F%3E%E5%88%87%E6%88%90%E5%9B%BA%E5%AE%9A%20KV%20%E5%9D%97%22%5D%0A%20%20%20%20S%20--%3E%20A%5B%22%E8%AF%B7%E6%B1%82%E5%8F%98%E9%95%BF%20%E2%86%92%20%E9%A2%86%E6%96%B0%E5%9D%97%22%5D%0A%20%20%20%20A%20--%3E%20B%5B%22%E8%AF%B7%E6%B1%82%E7%BB%93%E6%9D%9F%20%E2%86%92%20%E8%BF%98%E5%9D%97%22%5D%0A%20%20%20%20B%20--%3E%20S%0A"})]),fallback:r(()=>[...t[0]||(t[0]=[a(" Loading... ",-1)])]),_:1})),t[6]||(t[6]=B('<ul><li>单请求最多能领的块数由上下文上限决定；提示加已生成的 token 超过上限，请求被拒绝。</li><li>能同时挂住多少路对话，取决于每路实际领了多少块，而不是路数乘以上限。短对话还块之后，显存立刻给下一路。</li></ul><h2 id="前缀缓存留下公共开头" tabindex="-1">前缀缓存留下公共开头 <a class="header-anchor" href="#前缀缓存留下公共开头" aria-label="Permalink to &quot;前缀缓存留下公共开头&quot;">​</a></h2><p>普通 KV 缓存只服务这一次请求，请求结束块就还回去。前缀缓存多留一步：下一次请求的开头若和已留住的块相同，这些块直接复用，这段 prefill 不用再算。</p><ul><li><strong>能命中的</strong>：稳定的开头，例如系统提示、工具说明、反复出现的模板。</li><li><strong>要重算的</strong>：用户这一轮新说的话，以及据此新生成的回答——开头对不上。</li></ul><p>命中省下的是 prefill 时间，decode 仍逐 token 生成，速度不因命中而变快。公共前缀越长、越稳定，省下的 prefill 越多。对话历史每轮都在变，命中率会停在「公共开头占总 token 的那一截」，不会接近百分之百。</p><h2 id="引擎日志在说什么" tabindex="-1">引擎日志在说什么 <a class="header-anchor" href="#引擎日志在说什么" aria-label="Permalink to &quot;引擎日志在说什么&quot;">​</a></h2><p>vLLM 约每 10 秒打一行，里面有五样东西。这一行是窗口平均，要把空闲算进去。</p><table tabindex="0"><thead><tr><th>字段</th><th>含义</th><th>注意</th></tr></thead><tbody><tr><td>提示吞吐</td><td>这 10 秒里 prefill 处理的 token 数</td><td>请求在窗口末尾才进来、或窗口大部分时间是空的，平均值会被拉低；不能换成「任意长度提示都按这个速度线性算完」</td></tr><tr><td>生成吞吐</td><td>这 10 秒里生成的 token 数</td><td>同样含空闲，窗口空闲时可能掉到每秒几个甚至 0；单次请求的逐 token 速度要单独计时，不用这行代替</td></tr><tr><td>正在跑/等的请求数</td><td>此刻在跑与排队的请求</td><td>配合 KV 占用判断显存是否被握住</td></tr><tr><td>KV 占用</td><td>GPU 上键值块占用比例</td><td>接近 0 表示采样时块已还回；占用升高且正在跑的请求数大于 0，表示此刻有请求握着块</td></tr><tr><td>前缀命中率</td><td>跨请求公共开头的复用比例</td><td>多半是累计口径，一天里移动很慢；它高只表示公共开头在被复用，不表示某路对话占满了显存</td></tr></tbody></table><p>引擎启动时还会打印可用的块数量。那一行若没留在日志里，在线的占用百分比就只是相对值，看不出显存里一共切了多少块。</p>',9))])}const D=o(u,[["render",k]]);export{b as __pageData,D as default};
